    Var i("i"), j("j");

    // RDom extents derived from the input buffers (fixed for this problem size).
    RDom ri(0, r.dim(0).extent(), "ri");  // 0 .. n-1
    RDom rj(0, p.dim(0).extent(), "rj");  // 0 .. m-1

