    //     for jo in tiles of j (parallel):
    //       for ri in 0..n-1:
    //         for ji in 0..tile-1 (vectorized):
    //           j = jo*tile + ji;
    //           s[j] += r[ri] * A[j, ri];
    //
    // For q(i):
    //   We want inner loop over i (rows) to keep q(i) contiguous.
    //   We split i into [io, ii], parallelize io, and vectorize ii:
    //
    //   Final loop shape (conceptual):
    //     for io in tiles of i (parallel):
    //       for rj in 0..m-1:
    //         for ii in 0..tile-1 (vectorized):
    //           i = io*tile + ii;
    //           q[i] += A[rj, i] * p[rj];
    // ------------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    Var jo("jo"), ji("ji");
    Var io("io"), ii("ii");

    // s_func: compute full 1D vector at root, then schedule the
    // reduction update in tiled, parallel, vectorized fashion.
    s_func.compute_root();

    s_func.update()
        .split(j, jo, ji, vec_width)   // j -> (jo, ji), ji is the inner tile index
        .reorder(ji, ri, jo)          // innermost: ji, then reduction ri, outermost jo
        .vectorize(ji)                // SIMD across contiguous j
