    // q_func: analogous schedule over i.
    q_func.compute_root();

    q_func.update()
        .split(i, io, ii, vec_width)  // i -> (io, ii)
        .reorder(ii, rj, io)          // innermost: ii, then reduction rj, outermost io
        .vectorize(ii)                // SIMD across contiguous i
        .parallel(io);                // parallelize tiles of i

    // JIT-compile both functions once, so timing measures only execution.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
