            .reorder(ji_s, ri, jo_s)
            .parallel(jo_s)
            .vectorize(ji_s);
    }

    // Schedule for q_func: parallel and vectorize over i
    {
        Var jo_q("jo_q"), ji_q("ji_q");

        // Pure definition: q(i) = 0
        q_func
            .compute_root()
            .split(i, jo_q, ji_q, vec_width)
            .parallel(jo_q)
            .vectorize(ji_q);

        // Update definition: q(i) += ...
        q_func.update()
            .split(i, jo_q, ji_q, vec_width)
            .reorder(ji_q, rj, jo_q)
            .parallel(jo_q)
            .vectorize(ji_q);
    }

    // JIT-compile both functions once, so timing measures only execution.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
