    //
    // Pure definition: set s[j] = 0.
    // We parallelize and vectorize across j; no memory reads from A here.
    s_func.compute_root()
          .split(j, j_outer, j_inner, vec)
          .parallel(j_outer)
          .vectorize(j_inner);

