    // Default loop nest (conceptual) is:
    //   for j:
    //     for ri:
    //       s[j] += r[ri] * A(j, ri)
    //
    // This walks A along its strided dimension (i), which is bad for locality.
    // We reorder to:
    //   for ri:
    //     for j:
    //       ...
    //
    // and then tile 'j' into [j_outer, j_inner], vectorizing j_inner and
    // parallelizing j_outer:
    //
    //   for j_outer (parallel):
    //     for ri:
    //       for j_inner (vectorized):
    //         ...
    s_func.update()
          // make ri outer, j inner
          .reorder(j, ri)
          // tile j for vectorization & parallelism
          .split(j, j_outer, j_inner, vec)
          // desired final order: outermost j_outer, then ri, then j_inner
          .reorder(j_inner, ri, j_outer)
          .parallel(j_outer)
          .vectorize(j_inner);

    // ---- Schedule for q_func (computes q[i]) ----
    //
    // Pure definition: q[i] = 0.
    // We parallelize and vectorize across i.
    q_func.compute_root()
          .split(i, i_outer, i_inner, vec)
          .parallel(i_outer)
          .vectorize(i_inner);

    // Update definition:
    // Default loop nest (conceptual) is:
    //   for i:
    //     for rj:
    //       q[i] += A(rj, i) * p[rj]
    //
    // Here rj indexes j, which is dimension 0 of A and contiguous.
    // We keep rj as the innermost loop, and vectorize it for good
    // memory access in A and p. We parallelize across i, which are
    // independent accumulations.
    //
    //   for i (parallel):
    //     for rj_outer:
    //       for rj_inner (vectorized):
    //         ...
    q_func.update()
          .split(rj, rj_outer, rj_inner, vec)
          // desired final order: outermost i, then rj_outer, then rj_inner
          .reorder(rj_inner, rj_outer, i)
          .parallel(i)
          .vectorize(rj_inner);

