    p_param.set(p);
    r_param.set(r);

    // Halide variables.
    Var i("i"), j("j");

    // Additional Vars for scheduling (tiling, parallelism, vectorization).
    Var jo("jo"), ji("ji");
    Var io("io"), ii("ii");

    // RDom extents derived from the input buffers (fixed for this problem size).
